// Map whatever the source sends into RealCognix's normalised lead.
const b = $json.body ?? $json;
const pick = (...k) => k.map(x => b[x]).find(v => v !== undefined && v !== '');
return [{ json: {
  intakeKey: pick('intakeKey', 'intake_key') ?? $json.query?.key,
  lead: {
    sourceKind: pick('sourceKind', 'source') ?? 'other',
    externalId: String(pick('id', 'lead_id', 'call_id') ?? ''),
    fullName: pick('name', 'full_name', 'fullName'),
    phone: String(pick('phone', 'mobile', 'caller', 'phone_number') ?? ''),
    email: pick('email'),
    city: pick('city'),
    message: pick('message', 'comments', 'requirement'),
    projectHint: pick('project', 'property'),
    budgetText: pick('budget'),
    bhkText: pick('bhk', 'configuration'),
    raw: b,
  },
}}];
